UPDATE comments
goods_id = #{goodsId}, user_id = #{userId}, content = #{content}, rating = #{rating}, images = #{images}, reply = #{reply}, status = #{status}, audit_comment = #{auditComment}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM comments c 
LEFT JOIN goods g ON c.goods_id = g.id 
WHERE g.seller_id = #{sellerId}
